export const DOMAINS = [
  { key: "concepts", label: "Core Cloud Concepts", weightPct: 20 },
  { key: "compute", label: "Compute & Storage", weightPct: 22 },
  { key: "networking", label: "Networking & Security", weightPct: 20 },
  { key: "data", label: "Databases & Data Services", weightPct: 16 },
  { key: "identity", label: "Identity & Governance", weightPct: 10 },
  { key: "pricing", label: "Pricing, Billing & Support", weightPct: 12 },
];

const questions = [
  // ── CORE CLOUD CONCEPTS ──────────────────────────────────────────────────────
  { id: 1, domain: "concepts", question: "A company wants to rent computing power and only pay for what it uses, without owning or maintaining the underlying servers, storage, and networking. What is this model called?", options: ["Software as a Service (SaaS)", "Infrastructure as a Service (IaaS)", "On-premises hosting", "Colocation"], answer: 1, explanation: "IaaS (e.g. AWS EC2, Azure Virtual Machines, Google Compute Engine) provides raw compute, storage, and networking building blocks that the customer manages, without owning physical hardware." },
  { id: 2, domain: "concepts", question: "A team wants to deploy code without managing servers, operating systems, or runtime patching, they just push their application and the platform handles scaling and infrastructure. Which model is this?", options: ["IaaS", "PaaS", "SaaS", "Colocation"], answer: 1, explanation: "PaaS (e.g. AWS Elastic Beanstalk, Azure App Service, Google App Engine) manages the underlying infrastructure and runtime, letting developers focus purely on application code." },
  { id: 3, domain: "concepts", question: "A business subscribes to an email and office productivity suite accessed entirely through a web browser, with no installation or infrastructure to manage. What model is this?", options: ["IaaS", "PaaS", "SaaS", "Hybrid cloud"], answer: 2, explanation: "SaaS (e.g. Microsoft 365, Google Workspace) delivers a complete, ready-to-use application over the internet, with the provider managing everything underneath." },
  { id: 4, domain: "concepts", question: "Which best describes a hybrid cloud strategy?", options: ["Using only one public cloud provider for everything", "Combining on-premises infrastructure with one or more public clouds, with integration between them", "Running two completely unrelated private data centers", "Using only free-tier cloud services"], answer: 1, explanation: "Hybrid cloud connects on-premises (or private cloud) infrastructure with public cloud resources, allowing workloads and data to move between them as needed." },
  { id: 5, domain: "concepts", question: "A company deliberately runs different workloads on AWS, Azure, and Google Cloud simultaneously, partly to avoid depending on a single vendor. What is this strategy called?", options: ["Hybrid cloud", "Multi-cloud", "Private cloud", "Edge computing"], answer: 1, explanation: "Multi-cloud specifically means using more than one public cloud provider, often to avoid vendor lock-in, meet data residency needs, or use each provider's particular strengths." },
  { id: 6, domain: "concepts", question: "What does 'elasticity' mean in the context of cloud computing?", options: ["The ability to permanently increase capacity and never scale down", "The ability to automatically scale resources up or down in response to real-time demand", "A fixed amount of compute allocated once per year", "The physical flexibility of server room cabling"], answer: 1, explanation: "Elasticity is the automatic, on-demand scaling of resources up during high demand and back down during low demand, so customers only pay for what they actually need at any given moment." },
  { id: 7, domain: "concepts", question: "Which financial shift does moving from on-premises data centers to the cloud typically represent?", options: ["From OpEx to CapEx", "From CapEx to OpEx", "Elimination of all IT spending", "A shift from monthly to one-time-only billing"], answer: 1, explanation: "On-premises infrastructure requires large upfront capital expenditure (CapEx) for hardware; cloud computing converts this into ongoing, usage-based operational expenditure (OpEx)." },
  { id: 8, domain: "concepts", question: "A retailer's website must stay online and responsive even if an entire data center loses power. Which cloud design principle addresses this most directly?", options: ["High availability through multi-zone or multi-region redundancy", "Using the cheapest possible single server", "Avoiding all use of load balancers", "Storing all data on a single physical disk"], answer: 0, explanation: "High availability is achieved by distributing resources across multiple availability zones or regions, so the failure of one location does not take the whole application down." },
  { id: 9, domain: "concepts", question: "What is the key difference between 'high availability' and 'disaster recovery'?", options: ["They are exactly the same thing", "High availability minimizes downtime during normal operation and localized failures, while disaster recovery is the plan for recovering after a major, catastrophic event", "Disaster recovery only applies to on-premises data centers", "High availability applies only to storage, never to compute"], answer: 1, explanation: "High availability keeps systems running through routine failures (like a single server going down), while disaster recovery is the broader strategy and tooling for restoring operations after major outages, such as a full region failure." },
  { id: 10, domain: "concepts", question: "Under the shared responsibility model used by every major cloud provider, who is generally responsible for securing the physical data centers and the hardware they run on?", options: ["The customer", "The cloud provider", "A third-party auditor", "No one, it is assumed to be secure by default"], answer: 1, explanation: "In the shared responsibility model, the cloud provider secures the physical infrastructure ('security of the cloud'), while the customer is responsible for securing what they put on it, such as data, access controls, and configurations ('security in the cloud')." },
  { id: 11, domain: "concepts", question: "A company stores unencrypted customer data in a publicly accessible cloud storage bucket. Under the shared responsibility model, who is at fault?", options: ["The cloud provider, because they own the infrastructure", "The customer, because configuring access controls and encryption for their own data is their responsibility", "No one, misconfigurations are not covered by shared responsibility", "The end users who uploaded the data"], answer: 1, explanation: "Cloud providers secure the underlying platform, but customers are responsible for how they configure access, encryption, and permissions on their own resources and data." },
  { id: 12, domain: "concepts", question: "What is a 'region' in the context of major cloud providers?", options: ["A single physical server", "A geographic area containing a cluster of data centers, often subdivided into availability zones", "A billing category", "A type of virtual machine"], answer: 1, explanation: "A region is a large geographic area (e.g. 'US East' or 'West Europe') containing multiple, physically separate data centers, letting customers place workloads near their users and across zones for resilience." },
  { id: 13, domain: "concepts", question: "What is an 'availability zone' (or 'zone')?", options: ["A marketing term with no real infrastructure meaning", "One or more discrete, physically separate data centers within a region, each with independent power and networking", "A single rack of servers", "A customer's billing account"], answer: 1, explanation: "Availability zones are physically isolated data centers within the same region, each with independent power, cooling, and networking, so a failure in one zone does not necessarily affect another." },
  { id: 14, domain: "concepts", question: "A media company wants to serve video content to users worldwide with minimal delay. Which concept addresses this most directly?", options: ["Reserved instances", "Edge locations and a content delivery network (CDN)", "A single central region", "Manual server replication done by hand"], answer: 1, explanation: "Edge locations, used by CDNs, cache content physically closer to end users around the world, reducing latency regardless of where the origin servers are located." },
  { id: 15, domain: "concepts", question: "Which of these is a genuine advantage cloud computing offers over traditional on-premises infrastructure?", options: ["Cloud computing removes all need for security practices", "Faster global reach: new resources can be deployed in minutes in regions around the world instead of months", "Cloud computing guarantees a company will never experience an outage", "On-premises infrastructure is always cheaper at any scale"], answer: 1, explanation: "One of cloud computing's biggest advantages is speed of global deployment, spinning up infrastructure in a new region in minutes rather than the months it would take to build a physical data center." },
  { id: 16, domain: "concepts", question: "What best describes 'economies of scale' as it applies to cloud providers?", options: ["Each individual customer pays more as the provider grows", "Because cloud providers buy hardware and build data centers at massive scale, their per-unit costs drop, and savings are often passed on to customers through lower prices", "Economies of scale only apply to physical retail stores", "It refers to scaling a single application vertically"], answer: 1, explanation: "Massive providers purchase hardware, power, and networking capacity at a scale individual companies cannot match, lowering their costs per unit, savings that are typically passed on through competitive, frequently-decreasing prices." },
  { id: 17, domain: "concepts", question: "A government agency is legally required to keep certain citizen data physically stored within national borders. Which cloud concept helps satisfy this?", options: ["Elasticity", "Data residency, achieved by selecting specific regions to store and process data", "Serverless computing", "Reserved capacity pricing"], answer: 1, explanation: "Data residency requirements are met by deliberately choosing cloud regions located within the required country or jurisdiction to store and process regulated data." },
  { id: 18, domain: "concepts", question: "What is 'vendor lock-in' in a cloud context?", options: ["A security feature that locks unauthorized users out of an account", "The difficulty and cost of switching from one cloud provider to another due to proprietary services, data formats, or architecture", "A requirement that all cloud accounts use two-factor authentication", "A type of firewall rule"], answer: 1, explanation: "Vendor lock-in describes how deeply relying on one provider's proprietary services can make migrating to another provider costly and complex, a key reason some organizations pursue multi-cloud or open-standard architectures." },
  { id: 19, domain: "concepts", question: "Which is the best example of using managed services to reduce 'undifferentiated heavy lifting'?", options: ["Manually patching and maintaining your own database server operating system", "Using a fully managed database service where the provider handles patching, backups, and failover", "Writing your own container orchestration system from scratch", "Hosting your own physical email servers"], answer: 1, explanation: "Managed services (like managed databases) let teams focus on their actual business logic instead of repetitive operational tasks like patching and backups, which the provider handles automatically." },
  { id: 20, domain: "concepts", question: "A startup founder says, 'we can test an idea with customers this week instead of waiting months to buy and rack servers.' Which cloud benefit are they describing?", options: ["Data residency", "Agility, the ability to quickly provision resources and experiment", "Vendor lock-in", "Sustained use discounts"], answer: 1, explanation: "Agility refers to the speed at which cloud resources can be provisioned, letting teams experiment and iterate quickly instead of waiting on hardware procurement cycles." },
  { id: 21, domain: "concepts", question: "Which statement about 'serverless' computing is accurate?", options: ["Serverless means there are no servers involved anywhere in the system", "Serverless means the customer does not have to provision or manage servers; the cloud provider handles the underlying infrastructure automatically", "Serverless applications cannot scale", "Serverless is another name for on-premises hosting"], answer: 1, explanation: "Serverless computing still runs on physical servers, but the provider fully manages provisioning, scaling, and infrastructure, so developers just deploy code without thinking about servers." },
  { id: 22, domain: "concepts", question: "A company needs strict control over its infrastructure for regulatory reasons and builds a cloud-like environment entirely within its own data center, used by only that one organization. What is this called?", options: ["Public cloud", "Private cloud", "Multi-cloud", "Community cloud"], answer: 1, explanation: "A private cloud is cloud-style infrastructure (self-service, virtualized, elastic) dedicated to a single organization, often built on-premises or in a dedicated hosted environment for control or compliance reasons." },

  // ── COMPUTE & STORAGE ─────────────────────────────────────────────────────────
  { id: 23, domain: "compute", question: "Which set of services are the closest cross-cloud equivalents for basic virtual machines?", options: ["AWS Lambda, Azure Functions, Google Cloud Functions", "AWS EC2, Azure Virtual Machines, Google Compute Engine", "AWS S3, Azure Blob Storage, Google Cloud Storage", "AWS RDS, Azure SQL Database, Google Cloud SQL"], answer: 1, explanation: "EC2, Azure VMs, and Compute Engine are each provider's core IaaS offering for renting virtual machines with configurable CPU, memory, and OS." },
  { id: 24, domain: "compute", question: "Which set of services are the closest cross-cloud equivalents for running short-lived, event-triggered code without managing servers?", options: ["AWS Lambda, Azure Functions, Google Cloud Functions", "AWS EC2, Azure Virtual Machines, Google Compute Engine", "AWS EKS, Azure AKS, Google GKE", "AWS Redshift, Azure Synapse, Google BigQuery"], answer: 0, explanation: "Lambda, Azure Functions, and Cloud Functions are each provider's Functions-as-a-Service (FaaS) offering, running code in response to events without any server management." },
  { id: 25, domain: "compute", question: "Which set of services are the closest cross-cloud equivalents for fully managed Kubernetes?", options: ["AWS ECS, Azure Container Apps, Google Cloud Run", "AWS EKS, Azure AKS (Azure Kubernetes Service), Google GKE (Google Kubernetes Engine)", "AWS Lambda, Azure Functions, Google Cloud Functions", "AWS Lightsail, Azure App Service, Google App Engine"], answer: 1, explanation: "EKS, AKS, and GKE are each provider's managed Kubernetes offering, handling the Kubernetes control plane so customers can focus on running containerized workloads." },
  { id: 26, domain: "compute", question: "Which set of services are the closest cross-cloud equivalents for a fully managed platform to deploy web applications with minimal infrastructure configuration?", options: ["AWS Elastic Beanstalk, Azure App Service, Google App Engine", "AWS S3, Azure Blob Storage, Google Cloud Storage", "AWS Direct Connect, Azure ExpressRoute, Google Cloud Interconnect", "AWS IAM, Azure Entra ID, Google Cloud IAM"], answer: 0, explanation: "Elastic Beanstalk, Azure App Service, and App Engine are each provider's PaaS for deploying web applications, handling the underlying servers, load balancing, and scaling automatically." },
  { id: 27, domain: "compute", question: "A team wants to run containers without managing any cluster or nodes at all, simply pointing at a container image and letting the platform scale it automatically, including to zero. Which type of service fits?", options: ["A traditional virtual machine", "A serverless container platform like AWS Fargate, Azure Container Apps, or Google Cloud Run", "A physical on-premises server", "A dedicated bare-metal host"], answer: 1, explanation: "Serverless container platforms (Fargate, Container Apps, Cloud Run) run containers without requiring the customer to provision or manage the underlying servers or cluster, scaling automatically including down to zero." },
  { id: 28, domain: "compute", question: "Which set of services are the closest cross-cloud equivalents for object storage (storing files like images, videos, and backups accessed via an API over HTTP)?", options: ["AWS S3, Azure Blob Storage, Google Cloud Storage", "AWS EBS, Azure managed disks, Google Persistent Disk", "AWS EFS, Azure Files, Google Filestore", "AWS RDS, Azure SQL Database, Google Cloud SQL"], answer: 0, explanation: "S3, Azure Blob Storage, and Cloud Storage are each provider's core object storage service, ideal for unstructured data like files, backups, and media accessed via API." },
  { id: 29, domain: "compute", question: "Which set of services are the closest cross-cloud equivalents for block storage that attaches to a single virtual machine, similar to a traditional hard drive?", options: ["AWS EBS (Elastic Block Store), Azure managed disks, Google Persistent Disk", "AWS S3, Azure Blob Storage, Google Cloud Storage", "AWS Glacier, Azure Archive Storage, Google Coldline Storage", "AWS CloudFront, Azure CDN, Google Cloud CDN"], answer: 0, explanation: "EBS, Azure managed disks, and Persistent Disk each provide block-level storage volumes that attach directly to a virtual machine, functioning like a traditional disk drive." },
  { id: 30, domain: "compute", question: "Which set of services are the closest cross-cloud equivalents for a fully managed, shared file system that multiple virtual machines can mount simultaneously?", options: ["AWS EFS (Elastic File System), Azure Files, Google Filestore", "AWS S3, Azure Blob Storage, Google Cloud Storage", "AWS EBS, Azure managed disks, Google Persistent Disk", "AWS Snowball, Azure Data Box, Google Transfer Appliance"], answer: 0, explanation: "EFS, Azure Files, and Filestore are managed network file systems that many virtual machines or containers can mount and access at the same time, unlike block storage which attaches to a single instance." },
  { id: 31, domain: "compute", question: "A media archive rarely accesses old footage but must retain it for years at the lowest possible cost, and can tolerate retrieval times of several hours. Which type of storage tier fits best?", options: ["Hot or standard storage tier", "Cold or archive storage tier (e.g. S3 Glacier, Azure Archive Storage, Google Coldline/Archive)", "In-memory caching only", "A dedicated high-performance SSD block volume"], answer: 1, explanation: "Archive/cold storage tiers are purpose-built for rarely accessed data, offering the lowest per-gigabyte storage cost in exchange for slower retrieval times, ideal for long-term archives." },
  { id: 32, domain: "compute", question: "What is the main architectural difference between a virtual machine and a container?", options: ["Containers each include a full guest operating system, while VMs share the host OS kernel", "VMs each include a full guest operating system, while containers share the host OS kernel and are more lightweight", "There is no difference; the terms are interchangeable", "Containers can only run on bare-metal servers, never in the cloud"], answer: 1, explanation: "A VM virtualizes an entire machine including its own OS kernel, making it heavier, while containers share the host's OS kernel and package only the application and its dependencies, making them lighter and faster to start." },
  { id: 33, domain: "compute", question: "Which workload is generally the best fit for a serverless functions platform (like Lambda, Azure Functions, or Cloud Functions) rather than a long-running virtual machine?", options: ["A monolithic application that must run continuously with dedicated in-memory state for weeks", "A short-lived task triggered by an event, like resizing an image right after it is uploaded", "A traditional relational database engine", "A dedicated gaming server requiring constant low-latency connections for hours at a time"], answer: 1, explanation: "Serverless functions are ideal for short-lived, event-driven tasks that start, run briefly, and stop, such as processing a file immediately after upload, since you are billed only for the execution time used." },
  { id: 34, domain: "compute", question: "What is 'auto scaling' in the context of compute services?", options: ["Manually adding servers once a year during a planning meeting", "Automatically adding or removing compute instances based on real-time demand or defined metrics like CPU usage", "A one-time setting that can never be changed", "A feature exclusive to on-premises data centers"], answer: 1, explanation: "Auto scaling automatically adjusts the number of running compute instances based on live demand or metrics, ensuring enough capacity during spikes while saving cost during quiet periods." },
  { id: 35, domain: "compute", question: "Which of these best describes 'Infrastructure as Code' (IaC)?", options: ["Manually clicking through a web console to create every resource each time", "Defining and provisioning infrastructure using machine-readable configuration files that can be versioned and reused", "A programming language used only for mobile app development", "A billing model unrelated to infrastructure provisioning"], answer: 1, explanation: "IaC tools (like Terraform, AWS CloudFormation, Azure Bicep/ARM templates, or Google Cloud Deployment Manager) let teams define infrastructure in code, enabling repeatable, version-controlled, and automated deployments." },
  { id: 36, domain: "compute", question: "A company wants a single infrastructure-as-code tool that can provision resources consistently across AWS, Azure, and Google Cloud at once. Which type of tool addresses this?", options: ["A provider-specific tool like AWS CloudFormation only", "A cloud-agnostic tool like Terraform, which supports multiple providers through a common configuration language", "A spreadsheet listing servers manually", "There is no such tool available"], answer: 1, explanation: "Terraform is a popular cloud-agnostic infrastructure-as-code tool that can define and provision resources across multiple cloud providers using a single, consistent workflow." },
  { id: 37, domain: "compute", question: "Why might a company choose managed Kubernetes (EKS, AKS, or GKE) over running its own self-hosted Kubernetes cluster?", options: ["Managed Kubernetes removes the need to write any application code", "The provider handles the operational burden of managing, patching, and scaling the Kubernetes control plane", "Self-hosted Kubernetes is always more secure", "Managed Kubernetes cannot run containers"], answer: 1, explanation: "With managed Kubernetes, the cloud provider operates and maintains the complex control plane components, reducing the operational overhead compared to running and patching a self-hosted cluster." },
  { id: 38, domain: "compute", question: "A company is migrating an old application 'as-is' onto cloud virtual machines with minimal changes, just to get off aging on-premises hardware quickly. What migration strategy is this?", options: ["Refactor", "Rehost ('lift and shift')", "Retire", "Repurchase"], answer: 1, explanation: "Rehosting, often called 'lift and shift', moves an application to the cloud with little or no code changes, typically the fastest way to exit a data center." },
  { id: 39, domain: "compute", question: "A company decides an old internal tool is no longer needed and simply shuts it down instead of migrating it to the cloud. What migration strategy is this?", options: ["Replatform", "Retain", "Retire", "Repurchase"], answer: 2, explanation: "Retiring means decommissioning an application entirely rather than migrating it, appropriate when the tool is no longer needed." },
  { id: 40, domain: "compute", question: "A company decides to stop maintaining its own custom-built CRM and instead subscribes to a SaaS CRM product. Which migration strategy does this represent?", options: ["Rehost", "Repurchase", "Retain", "Refactor"], answer: 1, explanation: "Repurchasing means replacing an existing application with a different product, commonly moving to a SaaS alternative rather than migrating the original software." },
  { id: 41, domain: "compute", question: "Which compute option generally gives a developer the most control over the operating system, patching schedule, and installed software?", options: ["A SaaS application", "A serverless function", "A virtual machine (IaaS)", "A fully managed PaaS platform"], answer: 2, explanation: "Virtual machines (IaaS) give the customer full control over the guest operating system, installed software, and configuration, more than PaaS, serverless, or SaaS, which abstract more of the stack away." },
  { id: 42, domain: "compute", question: "What is the main tradeoff of choosing more abstracted compute options like PaaS or serverless over raw virtual machines?", options: ["There is no tradeoff; PaaS and serverless are always strictly better", "Less operational overhead and faster development, but reduced control over the underlying infrastructure and OS", "PaaS and serverless always cost more than virtual machines regardless of usage", "PaaS and serverless cannot scale automatically"], answer: 1, explanation: "Higher abstraction levels like PaaS and serverless reduce the operational burden and speed up development, but customers give up some control over the underlying infrastructure in exchange." },
  { id: 43, domain: "compute", question: "A company needs to transfer 200 terabytes of archival data into the cloud and their internet connection would take months. Which type of solution addresses this?", options: ["A faster web browser", "A physical data transfer appliance shipped to the customer, like AWS Snowball, Azure Data Box, or Google Transfer Appliance", "Increasing the number of virtual machines", "Using a smaller storage tier"], answer: 1, explanation: "For very large datasets where network transfer would be impractically slow, providers offer physical appliances that are shipped to the customer, loaded with data, and shipped back to be uploaded directly into the cloud." },
  { id: 44, domain: "compute", question: "What best describes a 'managed database service' compared to running a database yourself on a virtual machine?", options: ["A managed database service requires the customer to manually patch the database engine", "A managed database service handles provisioning, patching, backups, and often failover automatically, while a self-managed database on a VM requires the customer to handle all of that", "There is no meaningful difference between the two", "Managed database services cannot be scaled"], answer: 1, explanation: "Managed database services (like RDS, Azure SQL Database, or Cloud SQL) take over operational tasks such as patching, backups, and failover, whereas a self-managed database on a VM leaves all of that to the customer." },
  { id: 45, domain: "compute", question: "A company wants to run stateless web application containers that automatically scale based on incoming HTTP traffic, without managing servers or a Kubernetes cluster. Which type of service is the best fit?", options: ["A dedicated bare-metal server", "A serverless container platform such as Cloud Run, AWS Fargate, or Azure Container Apps", "A managed relational database", "An on-premises virtual machine"], answer: 1, explanation: "Serverless container platforms are designed exactly for this use case: stateless, HTTP-triggered containers that scale automatically (including to zero) without any server or cluster management." },
  { id: 46, domain: "compute", question: "Why do cloud providers offer multiple compute instance 'families' or 'sizes' (e.g. general purpose, compute-optimized, memory-optimized)?", options: ["To confuse customers with unnecessary choice", "So customers can match the hardware profile (CPU, memory, storage, networking) to their specific workload for better performance and cost efficiency", "Because all workloads perform identically regardless of instance type", "Purely for marketing purposes with no real technical difference"], answer: 1, explanation: "Different workloads have different resource needs; instance families let customers choose hardware profiles optimized for CPU-heavy, memory-heavy, storage-heavy, or balanced workloads to get the best performance per dollar." },

  // ── NETWORKING & SECURITY ──────────────────────────────────────────────────────
  { id: 47, domain: "networking", question: "Which set of concepts are the closest cross-cloud equivalents for a logically isolated private network within a cloud provider?", options: ["Amazon VPC, Azure Virtual Network (VNet), Google Cloud VPC", "AWS S3, Azure Blob Storage, Google Cloud Storage", "AWS Lambda, Azure Functions, Google Cloud Functions", "AWS IAM, Azure Entra ID, Google Cloud IAM"], answer: 0, explanation: "A VPC (AWS/Google) or VNet (Azure) is a logically isolated section of the cloud where a customer can launch resources within a private IP address range they control." },
  { id: 48, domain: "networking", question: "Which set of services are the closest cross-cloud equivalents for a managed DNS service?", options: ["AWS Route 53, Azure DNS, Google Cloud DNS", "AWS CloudFront, Azure CDN, Google Cloud CDN", "AWS Direct Connect, Azure ExpressRoute, Google Cloud Interconnect", "AWS WAF, Azure Front Door WAF, Google Cloud Armor"], answer: 0, explanation: "Route 53, Azure DNS, and Cloud DNS are each provider's managed Domain Name System service for translating domain names into IP addresses." },
  { id: 49, domain: "networking", question: "Which set of services are the closest cross-cloud equivalents for a dedicated, private network connection between an on-premises data center and the cloud (bypassing the public internet)?", options: ["AWS Direct Connect, Azure ExpressRoute, Google Cloud Interconnect", "AWS Route 53, Azure DNS, Google Cloud DNS", "AWS S3, Azure Blob Storage, Google Cloud Storage", "AWS CloudFront, Azure CDN, Google Cloud CDN"], answer: 0, explanation: "Direct Connect, ExpressRoute, and Cloud Interconnect each provide a dedicated, private network link between a customer's premises and the cloud provider's network, avoiding the public internet." },
  { id: 50, domain: "networking", question: "Which set of services are the closest cross-cloud equivalents for a content delivery network (CDN) that caches content at edge locations close to end users?", options: ["AWS CloudFront, Azure CDN, Google Cloud CDN", "AWS EBS, Azure managed disks, Google Persistent Disk", "AWS RDS, Azure SQL Database, Google Cloud SQL", "AWS IAM, Azure Entra ID, Google Cloud IAM"], answer: 0, explanation: "CloudFront, Azure CDN, and Cloud CDN each cache content at globally distributed edge locations to reduce latency for end users, regardless of where the origin server sits." },
  { id: 51, domain: "networking", question: "What is the primary purpose of a load balancer?", options: ["To permanently store customer data", "To distribute incoming network traffic across multiple servers or instances so no single one is overwhelmed", "To encrypt data at rest", "To manage user identities and permissions"], answer: 1, explanation: "Load balancers distribute incoming requests across multiple backend servers, improving availability and preventing any single instance from becoming a bottleneck or single point of failure." },
  { id: 52, domain: "networking", question: "What is a 'subnet' within a virtual network (VPC/VNet)?", options: ["A backup copy of the entire network", "A smaller, segmented range of IP addresses within a larger virtual network, often used to separate public-facing and private resources", "A type of firewall rule", "A billing category for network usage"], answer: 1, explanation: "Subnets divide a virtual network into smaller IP address ranges, commonly used to isolate resources, for example placing web servers in a public subnet and databases in a private subnet." },
  { id: 53, domain: "networking", question: "Which of these best describes a 'security group' (AWS) or equivalent (Network Security Group in Azure, firewall rules in Google Cloud)?", options: ["A physical security team that patrols the data center", "A virtual firewall that controls inbound and outbound traffic to specific resources based on defined rules", "A pricing tier for premium support", "A tool for managing DNS records"], answer: 1, explanation: "Security groups (or their Azure/GCP equivalents) act as virtual firewalls at the resource level, controlling which traffic is allowed in and out based on protocol, port, and source/destination rules." },
  { id: 54, domain: "networking", question: "A company wants to connect its office network to its cloud VPC over the public internet, but with an encrypted tunnel. Which type of connection fits?", options: ["A dedicated private connection like Direct Connect", "A Virtual Private Network (VPN) connection", "A content delivery network", "A managed DNS zone"], answer: 1, explanation: "A VPN creates an encrypted tunnel over the public internet between an on-premises network and the cloud, a faster and cheaper option than a dedicated private connection, though generally with less consistent performance." },
  { id: 55, domain: "networking", question: "Why might a company choose a dedicated connection (Direct Connect / ExpressRoute / Cloud Interconnect) over a standard VPN?", options: ["Dedicated connections are always free", "Dedicated connections offer more consistent bandwidth, lower latency, and bypass the unpredictable public internet entirely", "VPNs cannot be encrypted", "Dedicated connections require no contract or setup time"], answer: 1, explanation: "Dedicated private connections provide more predictable performance and higher bandwidth than internet-based VPNs, valuable for latency-sensitive or high-throughput workloads, at a higher cost and setup complexity." },
  { id: 56, domain: "networking", question: "What does encryption 'in transit' protect against, as opposed to encryption 'at rest'?", options: ["It protects data while it is stored on disk", "It protects data while it is moving across a network, such as between a client and a server", "It has nothing to do with security", "It only applies to email traffic"], answer: 1, explanation: "Encryption in transit (typically via TLS/HTTPS) protects data as it travels across networks, while encryption at rest protects data while it is stored on disk, both are needed for comprehensive protection." },
  { id: 57, domain: "networking", question: "Which set of services are the closest cross-cloud equivalents for a managed web application firewall protecting against common web exploits?", options: ["AWS WAF, Azure Web Application Firewall, Google Cloud Armor", "AWS Route 53, Azure DNS, Google Cloud DNS", "AWS S3, Azure Blob Storage, Google Cloud Storage", "AWS EC2, Azure Virtual Machines, Google Compute Engine"], answer: 0, explanation: "AWS WAF, Azure's Web Application Firewall, and Google Cloud Armor each filter and monitor HTTP traffic to protect web applications from common exploits like SQL injection and cross-site scripting." },
  { id: 58, domain: "networking", question: "What is the purpose of 'VPC peering' or 'VNet peering'?", options: ["To permanently merge two cloud accounts into one billing entity", "To connect two separate virtual networks so resources in each can communicate privately, without traversing the public internet", "To create a public website", "To encrypt a single virtual machine's local disk"], answer: 1, explanation: "Network peering privately connects two separate virtual networks (even across different accounts or projects) so resources can communicate using private IP addresses, without routing through the public internet." },
  { id: 59, domain: "networking", question: "A company running services in multiple cloud regions wants traffic automatically routed to the nearest healthy region for lower latency and resilience. Which concept addresses this?", options: ["A single subnet", "Global load balancing across regions", "A single availability zone", "Local-only DNS with no health checks"], answer: 1, explanation: "Global load balancing distributes traffic across multiple regions based on proximity and health checks, improving both latency and resilience if one region has issues." },
  { id: 60, domain: "networking", question: "What is 'DDoS protection' designed to defend against?", options: ["Employees losing their laptops", "Distributed Denial of Service attacks, where attackers flood a system with traffic to make it unavailable to legitimate users", "Accidental deletion of files", "Slow internal network speeds"], answer: 1, explanation: "DDoS protection services (like AWS Shield, Azure DDoS Protection, or Google Cloud Armor) detect and mitigate large-scale traffic floods designed to overwhelm and take down a service." },
  { id: 61, domain: "networking", question: "Which best describes the 'principle of least privilege' as applied to network and resource access?", options: ["Giving every user full administrator access by default for convenience", "Granting users and systems only the minimum access necessary to perform their required tasks, nothing more", "Removing all access controls entirely", "Applying the same permissions to every resource regardless of sensitivity"], answer: 1, explanation: "Least privilege means granting only the access required to do a specific job, reducing the potential damage from a compromised account or misconfiguration." },
  { id: 62, domain: "networking", question: "A company wants to inspect and filter outbound traffic from its private cloud subnets before it reaches the internet. Which type of resource is typically used?", options: ["A NAT gateway combined with security controls, or a dedicated network firewall appliance", "A content delivery network", "A managed relational database", "An identity provider"], answer: 0, explanation: "Outbound traffic from private subnets is commonly routed through a NAT gateway (for address translation) and/or a network firewall for inspection and filtering before reaching the public internet." },
  { id: 63, domain: "networking", question: "What is the main benefit of placing a database server in a private subnet rather than a public one?", options: ["It makes the database faster automatically", "It prevents the database from being directly reachable from the public internet, reducing its attack surface", "It has no security benefit at all", "It automatically encrypts all stored data"], answer: 1, explanation: "Placing sensitive resources like databases in a private subnet (with no direct route to the internet) significantly reduces their exposure to external attacks, forcing access through controlled paths like an application tier." },
  { id: 64, domain: "networking", question: "Which of the following is an example of 'defense in depth' in cloud network security?", options: ["Relying on a single firewall rule as the only security control", "Combining multiple layers such as network segmentation, security groups, encryption, and identity controls, so no single failure compromises the whole system", "Disabling all logging to improve performance", "Using the same password for every account"], answer: 1, explanation: "Defense in depth layers multiple independent security controls (network, identity, encryption, monitoring) so that the failure of any single layer does not fully compromise the system." },
  { id: 65, domain: "networking", question: "What does TLS/SSL primarily provide when a user visits a website over HTTPS?", options: ["Faster page load times only", "Encrypted, authenticated communication between the browser and the server", "Automatic backups of the website's database", "A discount on cloud storage costs"], answer: 1, explanation: "TLS/SSL (the 'S' in HTTPS) encrypts traffic between client and server and verifies the server's identity via certificates, protecting data in transit from eavesdropping and tampering." },
  { id: 66, domain: "networking", question: "A company wants to give a partner organization access to a specific application without exposing its entire internal network. Which approach is most appropriate?", options: ["Sharing the company's root account credentials", "Exposing only the specific application through a tightly scoped, authenticated endpoint, using private connectivity or an API gateway", "Disabling all firewalls for simplicity", "Placing every internal server directly on the public internet"], answer: 1, explanation: "Exposing only the minimal necessary surface (a specific application or API) through controlled, authenticated access follows least-privilege network design, rather than exposing the whole internal network." },
  { id: 67, domain: "networking", question: "What is the purpose of network flow logs (such as VPC Flow Logs)?", options: ["To store customer application data long-term", "To record metadata about network traffic (source, destination, ports, and whether it was allowed or denied) for monitoring and troubleshooting", "To automatically block all incoming traffic", "To replace the need for a firewall entirely"], answer: 1, explanation: "Flow logs capture metadata about IP traffic going in and out of network interfaces, useful for security analysis, troubleshooting connectivity issues, and auditing." },
  { id: 68, domain: "networking", question: "Which best describes 'zero trust' network security?", options: ["Trusting every device and user automatically once they are inside the corporate network perimeter", "Continuously verifying every user and device attempting to access resources, regardless of whether the request originates inside or outside the traditional network perimeter", "Removing all authentication requirements to speed up access", "A model that only applies to on-premises networks, never the cloud"], answer: 1, explanation: "Zero trust assumes no user or device should be automatically trusted, even inside the network perimeter, and instead continuously verifies identity and context for every access request." },

  // ── DATABASES & DATA SERVICES ──────────────────────────────────────────────────
  { id: 69, domain: "data", question: "Which set of services are the closest cross-cloud equivalents for a fully managed relational database (MySQL/PostgreSQL/SQL Server style)?", options: ["AWS RDS, Azure SQL Database, Google Cloud SQL", "AWS DynamoDB, Azure Cosmos DB, Google Firestore", "AWS Redshift, Azure Synapse Analytics, Google BigQuery", "AWS S3, Azure Blob Storage, Google Cloud Storage"], answer: 0, explanation: "RDS, Azure SQL Database, and Cloud SQL are each provider's managed relational database service, handling patching, backups, and failover for traditional SQL-based workloads." },
  { id: 70, domain: "data", question: "Which set of services are the closest cross-cloud equivalents for a fully managed NoSQL key-value/document database designed for massive scale and low latency?", options: ["AWS DynamoDB, Azure Cosmos DB, Google Firestore/Bigtable", "AWS RDS, Azure SQL Database, Google Cloud SQL", "AWS Redshift, Azure Synapse Analytics, Google BigQuery", "AWS Glacier, Azure Archive Storage, Google Coldline Storage"], answer: 0, explanation: "DynamoDB, Cosmos DB, and Firestore/Bigtable are each provider's flagship NoSQL database offerings, built for horizontal scale and low-latency access patterns that differ from traditional relational databases." },
  { id: 71, domain: "data", question: "Which set of services are the closest cross-cloud equivalents for a cloud data warehouse used for large-scale SQL analytics?", options: ["AWS Redshift, Azure Synapse Analytics, Google BigQuery", "AWS RDS, Azure SQL Database, Google Cloud SQL", "AWS DynamoDB, Azure Cosmos DB, Google Firestore", "AWS EFS, Azure Files, Google Filestore"], answer: 0, explanation: "Redshift, Azure Synapse Analytics, and BigQuery are each provider's data warehouse solution, optimized for running complex analytical queries across very large datasets." },
  { id: 72, domain: "data", question: "What is the fundamental difference between a relational (SQL) database and a NoSQL database?", options: ["Relational databases cannot store any text data", "Relational databases use structured tables with fixed schemas and relationships, while NoSQL databases use flexible models (key-value, document, wide-column, graph) often without a fixed schema", "NoSQL databases are always faster in every situation", "There is no meaningful difference between the two"], answer: 1, explanation: "Relational databases organize data into structured tables with defined schemas and support complex joins, while NoSQL databases favor flexible schemas and models optimized for specific access patterns and horizontal scale." },
  { id: 73, domain: "data", question: "A company is building a product catalog where each item has wildly different attributes, and they expect massive, unpredictable read traffic. Which type of database is generally a better initial fit?", options: ["A rigid relational database with a fixed schema for every possible attribute", "A NoSQL document database that easily accommodates varying attributes per item and scales horizontally", "A local spreadsheet file", "A single flat text file"], answer: 1, explanation: "Document-oriented NoSQL databases handle varying, semi-structured data well and are designed to scale horizontally for high-traffic, flexible-schema use cases like product catalogs." },
  { id: 74, domain: "data", question: "A financial application needs strict transactional guarantees (ACID compliance) for money transfers between accounts. Which type of database is typically the safest choice?", options: ["An eventually-consistent NoSQL key-value store", "A relational database with strong ACID transaction support", "A flat CSV file", "An in-memory cache with no persistence"], answer: 1, explanation: "Traditional relational databases are designed around ACID (Atomicity, Consistency, Isolation, Durability) guarantees, which are critical for financial transactions where partial or inconsistent updates cannot be tolerated." },
  { id: 75, domain: "data", question: "What is the main purpose of database read replicas?", options: ["To permanently delete old data", "To offload read traffic from the primary database by serving read queries from one or more synchronized copies", "To encrypt the primary database", "To reduce the number of available database connections"], answer: 1, explanation: "Read replicas are synchronized copies of a database used to handle read-heavy traffic, improving performance and scalability by taking load off the primary database, which continues to handle writes." },
  { id: 76, domain: "data", question: "What does 'database sharding' (horizontal partitioning) accomplish?", options: ["It compresses a database into a single smaller file", "It splits a large dataset across multiple database instances or partitions, so no single node has to hold or process all the data", "It automatically deletes duplicate rows", "It converts a NoSQL database into a relational one"], answer: 1, explanation: "Sharding distributes data across multiple database partitions or servers, allowing a system to scale beyond what a single database instance could handle." },
  { id: 77, domain: "data", question: "Which type of service is best suited for building a real-time streaming data pipeline (e.g. processing clickstream events as they happen)?", options: ["A static object storage bucket", "A stream processing service such as AWS Kinesis, Azure Stream Analytics, or Google Dataflow/Pub-Sub", "A monthly batch report generator only", "A single relational database table"], answer: 1, explanation: "Stream processing services are purpose-built to ingest, process, and analyze continuous event data in near real time, unlike batch-only or static storage tools." },
  { id: 78, domain: "data", question: "What is a 'data lake' typically used for?", options: ["Storing only pre-processed, perfectly structured relational tables", "Storing vast amounts of raw data in its native format (structured, semi-structured, and unstructured) for later processing and analysis", "Replacing the need for any database entirely", "A synonym for a single virtual machine's local disk"], answer: 1, explanation: "A data lake stores raw data of any format at scale, often in object storage, to be processed, transformed, and analyzed later, in contrast to a data warehouse which stores structured, already-modeled data." },
  { id: 79, domain: "data", question: "What is the key difference between a data lake and a data warehouse?", options: ["They are exactly the same thing", "A data lake stores raw data in native formats for flexible future use, while a data warehouse stores structured, cleaned, and modeled data optimized for fast analytical queries", "Data warehouses can only store images and video", "Data lakes cannot store structured data"], answer: 1, explanation: "Data lakes prioritize flexibility by storing raw data of any type, while data warehouses store curated, structured data specifically modeled and optimized for business intelligence and analytical queries." },
  { id: 80, domain: "data", question: "A company wants to build dashboards and visual reports on top of its data warehouse for business stakeholders. Which category of tool is designed for this?", options: ["A business intelligence (BI) tool, such as Looker, Amazon QuickSight, or Power BI", "A raw object storage bucket", "A firewall configuration tool", "An identity and access management console"], answer: 0, explanation: "BI tools connect to data warehouses and other data sources to build interactive dashboards, visualizations, and reports for business decision-making." },
  { id: 81, domain: "data", question: "What is the purpose of automated database backups?", options: ["To make the database run faster", "To create recoverable snapshots of data so it can be restored in case of accidental deletion, corruption, or disaster", "To permanently reduce storage costs to zero", "To automatically scale the database horizontally"], answer: 1, explanation: "Automated backups create point-in-time snapshots that let organizations recover data after accidental deletion, corruption, or a larger outage, a core part of any disaster recovery plan." },
  { id: 82, domain: "data", question: "What does 'database failover' mean in a managed database service with a standby replica?", options: ["Permanently shutting down the database", "Automatically switching operations to a standby replica if the primary database instance becomes unavailable, to minimize downtime", "Deleting all data and starting over", "Reducing the database to read-only mode forever"], answer: 1, explanation: "Failover automatically promotes a standby replica to become the new primary if the original primary fails, helping maintain availability with minimal manual intervention." },
  { id: 83, domain: "data", question: "Which of the following is an example of 'extract, transform, load' (ETL) processing?", options: ["Simply storing raw files without any changes", "Pulling data from a source system, cleaning and reshaping it, and loading it into a data warehouse for analysis", "Deleting a database table", "Encrypting a file at rest"], answer: 1, explanation: "ETL pipelines extract data from source systems, transform it into a clean and consistent structure, and load it into a destination such as a data warehouse, a foundational pattern in data engineering." },
  { id: 84, domain: "data", question: "A company wants to run machine learning models on top of the data stored in its cloud data warehouse or data lake without exporting the data elsewhere. Which type of service category enables this?", options: ["A managed AI/ML platform integrated with the data platform, such as SageMaker, Azure Machine Learning, or Vertex AI", "A basic DNS service", "A content delivery network", "A firewall management console"], answer: 0, explanation: "Managed AI/ML platforms (SageMaker, Azure Machine Learning, Vertex AI) integrate directly with each provider's storage and data warehouse services, letting teams train and deploy models without manually moving data around." },
  { id: 85, domain: "data", question: "What is a key advantage of a serverless data warehouse (like BigQuery) compared to a traditional, cluster-based data warehouse?", options: ["It requires manually provisioning and resizing clusters for every query", "Customers can run large-scale SQL analytics without provisioning or managing any underlying servers or clusters", "It cannot scale beyond a single server", "It only works with unstructured data"], answer: 1, explanation: "Serverless data warehouses abstract away cluster management entirely, automatically allocating resources per query, so customers do not need to size, provision, or maintain infrastructure themselves." },
  { id: 86, domain: "data", question: "Which factor should most influence the choice between a relational database and a NoSQL database for a new application?", options: ["Which one has a more appealing logo", "The application's data structure, consistency requirements, and expected access/scale patterns", "Always choosing whichever one is newest", "The number of letters in the database's name"], answer: 1, explanation: "The right database choice depends on concrete factors: how structured the data is, whether strong transactional consistency is required, and the expected scale and query patterns, not superficial preferences." },

  // ── IDENTITY & GOVERNANCE ───────────────────────────────────────────────────────
  { id: 87, domain: "identity", question: "Which set of services are the closest cross-cloud equivalents for managing user identities, permissions, and access policies?", options: ["AWS IAM, Microsoft Entra ID (formerly Azure AD), Google Cloud IAM", "AWS S3, Azure Blob Storage, Google Cloud Storage", "AWS CloudFront, Azure CDN, Google Cloud CDN", "AWS RDS, Azure SQL Database, Google Cloud SQL"], answer: 0, explanation: "AWS IAM, Microsoft Entra ID, and Google Cloud IAM are each provider's core identity and access management service for controlling who can do what within an account or project." },
  { id: 88, domain: "identity", question: "What is the 'principle of least privilege' when applied to identity and access management?", options: ["Giving every employee full administrator rights for simplicity", "Granting each user or system only the specific permissions required to perform their job, and nothing more", "Never granting any permissions at all", "Applying identical permissions to every account regardless of role"], answer: 1, explanation: "Least privilege limits access to only what is strictly necessary, reducing the potential damage if credentials are compromised or misused." },
  { id: 89, domain: "identity", question: "What is Multi-Factor Authentication (MFA) designed to do?", options: ["Speed up the login process by removing password requirements", "Require a second form of verification beyond a password, such as a code from a mobile app, to confirm a user's identity", "Automatically back up user data", "Encrypt data stored in a database"], answer: 1, explanation: "MFA adds a second layer of verification beyond a password, such as a one-time code or biometric check, significantly reducing the risk of account compromise from stolen credentials alone." },
  { id: 90, domain: "identity", question: "What is the difference between an IAM 'user' and an IAM 'role' (or equivalent managed identity)?", options: ["They are identical concepts with different names", "A user typically represents a specific person or application with long-term credentials, while a role is a set of permissions that can be temporarily assumed by a user, service, or resource", "Roles can only be assigned to physical hardware, never software", "Users can never be granted permissions"], answer: 1, explanation: "A user generally has persistent credentials tied to a specific identity, while a role defines a set of permissions that can be assumed temporarily, commonly used to grant services or federated identities scoped, short-lived access." },
  { id: 91, domain: "identity", question: "Which set of concepts are the closest cross-cloud equivalents for organizing multiple accounts or projects under a centralized hierarchy for billing and policy management?", options: ["AWS Organizations (accounts), Azure Management Groups (subscriptions), Google Cloud Organization (folders/projects)", "AWS IAM roles, Azure security groups, Google Cloud service accounts", "AWS S3 buckets, Azure Blob containers, Google Cloud Storage buckets", "AWS CloudTrail, Azure Activity Log, Google Cloud Audit Logs"], answer: 0, explanation: "AWS Organizations, Azure Management Groups, and Google Cloud's Organization/Folders hierarchy each let companies group multiple accounts, subscriptions, or projects under centralized governance and billing." },
  { id: 92, domain: "identity", question: "Which set of services are the closest cross-cloud equivalents for enforcing organization-wide guardrails on what actions are allowed, regardless of individual user permissions?", options: ["AWS Service Control Policies (SCPs), Azure Policy, Google Cloud Organization Policy Service", "AWS IAM users, Azure AD users, Google Cloud IAM members", "AWS Route 53, Azure DNS, Google Cloud DNS", "AWS S3, Azure Blob Storage, Google Cloud Storage"], answer: 0, explanation: "SCPs, Azure Policy, and the Organization Policy Service each let administrators set organization-wide guardrails that restrict what actions are possible, even for users who otherwise have broad permissions." },
  { id: 93, domain: "identity", question: "What is a 'service account' (or managed identity) used for?", options: ["Only for human employees to log into the console", "Providing an identity that applications or services (not humans) can use to authenticate and access cloud resources programmatically", "Storing customer credit card information", "Replacing the need for any access control"], answer: 1, explanation: "Service accounts (or managed identities in Azure) give non-human entities, such as applications or virtual machines, their own identity to securely access other cloud resources without embedding long-lived credentials in code." },
  { id: 94, domain: "identity", question: "Why is hardcoding long-term access keys directly into application source code considered a poor security practice?", options: ["It has no downsides at all", "If the code is exposed (e.g. committed to a public repository), the credentials can be stolen and misused indefinitely until manually revoked", "Hardcoded keys automatically expire after one use", "It is actually a recommended best practice by all cloud providers"], answer: 1, explanation: "Hardcoded credentials are a common source of security breaches; if leaked, they can be used by attackers until someone notices and manually revokes them. Best practice is to use roles, managed identities, or secrets managers instead." },
  { id: 95, domain: "identity", question: "Which set of services are the closest cross-cloud equivalents for securely storing and retrieving secrets like API keys, passwords, and certificates?", options: ["AWS Secrets Manager, Azure Key Vault, Google Cloud Secret Manager", "AWS S3, Azure Blob Storage, Google Cloud Storage", "AWS CloudWatch, Azure Monitor, Google Cloud Monitoring", "AWS Route 53, Azure DNS, Google Cloud DNS"], answer: 0, explanation: "Secrets Manager, Azure Key Vault, and Secret Manager each provide secure, centralized storage for sensitive values like API keys and passwords, with access controlled via IAM rather than being embedded in code." },
  { id: 96, domain: "identity", question: "What is the purpose of tagging or labeling cloud resources?", options: ["Tags have no practical use and are purely decorative", "Attaching metadata (like project name, cost center, or environment) to resources for organization, cost tracking, and automation", "Tags automatically encrypt the resources they are attached to", "Tags are required before a resource can be created and cannot be changed afterward"], answer: 1, explanation: "Tags/labels attach searchable metadata to resources, commonly used to track costs by project or department, organize resources, and drive automation rules." },
  { id: 97, domain: "identity", question: "What does an audit log service like AWS CloudTrail, Azure Activity Log, or Google Cloud Audit Logs primarily provide?", options: ["A record of every API call and administrative action taken within an account, useful for security review and compliance", "Automatic encryption of all stored data", "A tool for writing application code", "A discount on compute costs"], answer: 0, explanation: "Audit logging services record who did what, when, and from where within a cloud account, essential for security investigations, compliance audits, and troubleshooting unexpected changes." },

  // ── PRICING, BILLING & SUPPORT ──────────────────────────────────────────────────
  { id: 98, domain: "pricing", question: "What is the core idea behind 'pay-as-you-go' cloud pricing?", options: ["Customers must pay a large fee upfront regardless of usage", "Customers are billed based on actual resource consumption, with no long-term commitment required", "All cloud services are entirely free", "Pricing is fixed regardless of how many resources are used"], answer: 1, explanation: "Pay-as-you-go pricing charges customers only for the resources they actually consume, with no upfront commitment, contrasting with traditional infrastructure that requires large capital purchases regardless of usage." },
  { id: 99, domain: "pricing", question: "A company commits to using a specific amount of compute capacity for one or three years in exchange for a significantly discounted rate compared to on-demand pricing. What is this pricing model generally called?", options: ["On-demand pricing", "Reserved or committed-use pricing (e.g. AWS Reserved Instances/Savings Plans, Azure Reserved VM Instances, Google Committed Use Discounts)", "Spot/preemptible pricing", "Free tier pricing"], answer: 1, explanation: "Reserved or committed-use pricing offers substantial discounts (often 30-70%) in exchange for a commitment to a set usage level over one or three years, ideal for predictable, steady-state workloads." },
  { id: 100, domain: "pricing", question: "A company runs flexible, interruptible batch processing jobs and wants the lowest possible compute cost, accepting that instances might be reclaimed by the provider with little notice. Which pricing model fits best?", options: ["Reserved/committed-use pricing", "Spot Instances (AWS) / Spot VMs (Azure) / Preemptible or Spot VMs (Google)", "Standard on-demand pricing", "A long-term enterprise contract"], answer: 1, explanation: "Spot/preemptible pricing offers steep discounts on spare compute capacity that the provider can reclaim with short notice, well suited to fault-tolerant, flexible workloads like batch processing, but not for critical, always-on systems." },
  { id: 101, domain: "pricing", question: "Which unique discount, offered automatically without any upfront commitment, is a distinguishing feature of Google Cloud's compute pricing compared to AWS and Azure?", options: ["Reserved Instances", "Sustained Use Discounts, which automatically apply as a VM runs for a larger portion of the billing month", "Spot pricing", "Free tier pricing"], answer: 1, explanation: "Google Cloud automatically applies Sustained Use Discounts as a virtual machine runs for a larger share of the billing month, without requiring any upfront reservation, a pricing feature not directly replicated by AWS or Azure." },
  { id: 102, domain: "pricing", question: "What is a cloud provider's 'free tier' generally intended for?", options: ["Running large-scale, revenue-generating production workloads at no cost indefinitely", "Letting new customers experiment with services at no or minimal cost, usually within defined usage limits or a limited time period", "A permanent replacement for paid services at any scale", "A discount available only to enterprise customers"], answer: 1, explanation: "Free tiers let individuals and companies try services with limited usage caps (or for a limited introductory period) at no charge, mainly for learning, prototyping, and small-scale experimentation." },
  { id: 103, domain: "pricing", question: "Which set of tools are the closest cross-cloud equivalents for estimating the cost of a planned cloud architecture before deploying it?", options: ["AWS Pricing Calculator, Azure Pricing Calculator, Google Cloud Pricing Calculator", "AWS IAM, Azure Entra ID, Google Cloud IAM", "AWS CloudTrail, Azure Activity Log, Google Cloud Audit Logs", "AWS Route 53, Azure DNS, Google Cloud DNS"], answer: 0, explanation: "Each major provider offers a web-based pricing calculator that lets customers estimate the monthly cost of a proposed architecture before committing to build it." },
  { id: 104, domain: "pricing", question: "Which set of tools are the closest cross-cloud equivalents for setting budgets, alerts, and analyzing historical cloud spending?", options: ["AWS Budgets/Cost Explorer, Azure Cost Management, Google Cloud Billing Reports/Budgets", "AWS Direct Connect, Azure ExpressRoute, Google Cloud Interconnect", "AWS Lambda, Azure Functions, Google Cloud Functions", "AWS S3, Azure Blob Storage, Google Cloud Storage"], answer: 0, explanation: "AWS Cost Explorer/Budgets, Azure Cost Management, and Google Cloud's Billing Reports/Budgets each help customers analyze past spending, forecast future costs, and set alerts when spending exceeds a threshold." },
  { id: 105, domain: "pricing", question: "A parent company wants to combine the usage of several linked child accounts onto a single invoice, and potentially unlock volume-based discounts. What billing feature enables this?", options: ["Free tier usage", "Consolidated billing, available through account/organization structures across all major providers", "Spot pricing", "A support plan upgrade"], answer: 1, explanation: "Consolidated billing combines usage across multiple linked accounts into a single invoice, simplifying finance operations and often unlocking volume discounts that individual accounts would not reach alone." },
  { id: 106, domain: "pricing", question: "Which type of support plan generally provides 24/7 access to technical support engineers and guaranteed response times for production-impacting issues?", options: ["The most basic, free support tier", "A business or enterprise-level paid support plan", "There is no such thing as tiered support in the cloud", "Only community forum support"], answer: 1, explanation: "Higher paid support tiers (like AWS Business/Enterprise, Azure's Professional Direct, or Google Cloud's Enhanced/Premium support) provide 24/7 access to engineers and defined response-time guarantees, unlike free or basic tiers." },
  { id: 107, domain: "pricing", question: "Why do all three major providers offer a free, basic level of support alongside paid tiers?", options: ["Because paid support does not actually exist", "So that all customers, even those not paying for premium support, still have access to billing help, documentation, and community resources", "Because free support includes guaranteed 1-hour response times for critical outages", "Because it is legally mandated in every country"], answer: 1, explanation: "Free/basic support tiers typically cover account and billing questions along with access to documentation and community forums, while faster guaranteed response times and dedicated technical guidance are reserved for paid tiers." },
  { id: 108, domain: "pricing", question: "A company wants to understand which internal department or project is responsible for a given portion of its cloud bill. Which practice best enables this?", options: ["Ignoring billing details entirely", "Consistently tagging or labeling resources by project, team, or cost center, then using cost allocation reports based on those tags", "Using only one shared account with no separation of any kind", "Disabling billing alerts"], answer: 1, explanation: "Consistent resource tagging combined with cost allocation reporting lets organizations break down spending by project, team, or environment, essential for internal chargeback and budget accountability." },
  { id: 109, domain: "pricing", question: "What is the general pricing pattern for cloud data transfer (bandwidth)?", options: ["All data transfer, in every direction, is always free on every provider", "Data transferred into the cloud is typically free or very cheap, while data transferred out to the internet is usually charged, sometimes significantly at high volumes", "Data transfer costs are identical regardless of destination", "Data transfer is billed only once per year regardless of volume"], answer: 1, explanation: "Cloud providers commonly charge little or nothing for inbound data transfer but do charge for outbound data transfer to the internet, a cost that can become significant for data-intensive or high-egress applications." },
  { id: 110, domain: "pricing", question: "Which best summarizes the overall economic argument in favor of cloud computing over traditional on-premises infrastructure for many organizations?", options: ["Cloud computing is always cheaper in every single scenario with no exceptions", "It converts large unpredictable upfront capital costs into flexible, usage-based operating costs, while reducing the operational burden of managing physical hardware", "Cloud computing eliminates the need for any technical staff whatsoever", "On-premises infrastructure has no valid use cases anymore"], answer: 1, explanation: "The economic case for cloud rests on converting CapEx into OpEx, matching costs more closely to actual usage, and offloading the operational burden of hardware management, though it is not universally cheaper in every scenario and the right choice depends on workload specifics." },
];

export default questions;
